FLATS = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]
FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb"}
STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.notes = FLATS if tonic in FLAT_TONICS else SHARPS
        name = tonic[0].upper() + tonic[1:]
        self.start = self.notes.index(name)

    def chromatic(self):
        return self.notes[self.start:] + self.notes[:self.start]

    def interval(self, intervals):
        pos = self.start
        result = [self.notes[pos]]
        for step in intervals:
            pos = (pos + STEPS[step]) % 12
            result.append(self.notes[pos])
        return result
